export const ANDROID_BASELINE=Object.freeze("0.2.3");
export function phaseForEvent(event){if(!Object.hasOwn(EVENTS,event))throw Error('Unknown UI event: '+event);return EVENTS[event];}
export function stateId(label){const id=Object.keys(PHASES).find(k=>PHASES[k]===label);if(!id)throw Error('Unknown UI state: '+label);return id;}
export function stage(phase){if(!STATE_META[phase])throw Error('Unknown UI phase: '+phase);return STATE_META[phase].stage;}
export function menuSelection(index,direction){return Math.max(0,Math.min(MENU.length-1,index+direction));}
